/**
 * Evidence & Predictability Explorer -- the study, one person at a time.
 *
 * The aggregate result says the twin lost to persistence. It cannot show what
 * that average is made of: 12 of 42 held-out participants were in fact better
 * served by the twin, and the people at the two ends of the predictability
 * range barely look like the same problem. This page makes that inspectable.
 *
 * WHERE THE NUMBERS COME FROM
 * All of them are read from data/participants.json, generated by
 * scripts/export_participant_explorer.py, which disaggregates the frozen
 * experiment's own held-out evaluation. Averaging what this page shows
 * reproduces the published aggregate exactly, at both K. Nothing is typed by
 * hand, no metric is invented, and the one categorical label used
 * (near-unpredictable / typical / well-predictable) comes from the thresholds
 * the ceiling analysis already publishes -- the rule is printed on screen.
 *
 * WHAT IS DELIBERATELY ABSENT
 * Per-participant confidence intervals. The study's intervals come from a
 * participant-clustered bootstrap over the cohort, which yields no interval
 * for a single person. Drawing one would be inventing uncertainty.
 */
import F from "../data/findings.json";
import HIST from "../data/historical_findings.json";
import { META, all, byId, fmt, hasSeries, illustrative, isScored, phases,
         rankByAutocorrelation, scoreAt, sorted, SORTS, unscoredReason }
  from "../lib/participants.js";
import { attachTooltips, legend, longitudinalSvg, MARK_LIMIT, marksVisible,
         VIEWS } from "../lib/longitudinal.js";

const esc = (s) => String(s ?? "").replace(/[&<>"']/g,
  (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const state = { id: null, view: "full", sort: "autocorrelation", desc: true,
                compare: null };

/** A tooltip trigger whose text is a definition, never a claim. */
function info(text) {
  return `<button class="ex-i" type="button" aria-label="What this means"
    data-tip="${esc(text)}">i</button>`;
}

function defaultParticipant() {
  // open on a participant whose series is published, so the first thing a
  // visitor sees is a real chart rather than an explanation of an absence
  const withChart = illustrative().filter((p) => isScored(p));
  if (withChart.length) {
    return withChart.reduce((a, b) =>
      (b.autocorrelation ?? -9) > (a.autocorrelation ?? -9) ? b : a).id;
  }
  const scored = sorted("autocorrelation", true).filter((p) => isScored(p));
  return (scored[0] || all()[0]).id;
}

/** Stated absence, never an empty chart. */
function seriesUnavailable() {
  return `<div class="msg">
    <b>This participant's observation series is not published.</b>
    The source archive is not redistributed, so the site ships the full
    observations for only ${META.nSeriesPublished} illustrative participants —
    ${ILLUSTRATIVE_NOTE}. Every participant's summary statistics and held-out
    results are shown in full, above and below.</div>`;
}

const ILLUSTRATIVE_NOTE = `chosen by a fixed rule: ${META.illustrativeRule}`;

/* ------------------------------------------------------------- evidence */
function evidencePanel(p) {
  const rank = rankByAutocorrelation(p);
  const k = scoreAt(p);
  const rows = [
    ["Observations", fmt.int(p.n_observations),
     "Stress reports this participant contributed to the prediction frame."],
    ["Span", `${fmt.int(p.span_days)} days`, "First to last report."],
    ["Within-person autocorrelation", fmt.f3(p.autocorrelation),
     META.definitions.autocorrelation],
    ["Variability (SD)", fmt.f2(p.variability_sd),
     META.definitions.variability_sd],
    ["Mean reported stress", fmt.f2(p.mean_stress),
     "Average of this participant's own reports, on the 1-5 scale."],
    ["Scored observations", k ? fmt.int(k.n_eval) : "—",
     META.definitions.warm_up],
  ];
  return `
  <section class="panel">
    <header><h3>Predictability evidence</h3>
      <span class="meta">how predictable is this person's pattern?</span></header>
    <div class="pad">
      <div class="ex-band ex-band-${esc(p.predictability_band || "none")}">
        <b>${esc(p.predictability_band || "no autocorrelation available")}</b>
        <span>r = ${fmt.f3(p.autocorrelation)}${rank
          ? ` · ${rank.position} of ${rank.of} participants by this measure` : ""}</span>
      </div>
      <p class="ex-rule">Band rule, from the ceiling analysis's own published
        thresholds: <code>${esc(META.definitions.predictability_band)}</code>
        ${info(META.definitions.band_source)}</p>
      <div class="gridwrap"><table class="grid ex-tbl">
        <tbody>${rows.map(([label, value, tip]) => `<tr>
          <th>${esc(label)} ${info(tip)}</th>
          <td class="num">${esc(value)}</td></tr>`).join("")}</tbody>
      </table></div>
      <p class="hint">${esc(META.uncertainty)}</p>
    </div>
  </section>`;
}

/* ------------------------------------------------- twin vs persistence */
function bar(value, max, cls) {
  const w = max > 0 ? Math.max(1, (value / max) * 100) : 0;
  return `<span class="ex-bar"><i class="${cls}" style="width:${w.toFixed(1)}%"></i></span>`;
}

function strategyPanel(p) {
  const k = scoreAt(p);
  if (!k) {
    return `
    <section class="panel">
      <header><h3>Twin versus persistence</h3></header>
      <div class="pad"><div class="msg">
        <b>Not scored for this participant.</b>
        ${esc(unscoredReason(p))}. No performance is shown, because none was
        measured.</div></div>
    </section>`;
  }
  const t = k.twin.macro_f1, q = k.persistence.macro_f1, max = Math.max(t, q);
  const d = k.twin_minus_persistence_macro_f1;
  const agg = F.headline.models;
  const aggT = agg.T_twin.macro_f1, aggP = agg.B1_persistence.macro_f1;
  const aggMax = Math.max(aggT, aggP);
  return `
  <section class="panel">
    <header><h3>Twin versus persistence</h3>
      <span class="meta">this participant, held out, K=${k.n_warmup} warm-up ·
        ${k.n_eval} scored</span></header>
    <div class="pad">
      <div class="ex-vs">
        <div class="ex-vs-row ${k.twin_better ? "win" : ""}">
          <span class="ex-vs-lab">Digital twin</span>
          ${bar(t, max, "b-twin")}<span class="num">${fmt.f4(t)}</span></div>
        <div class="ex-vs-row ${k.twin_better ? "" : "win"}">
          <span class="ex-vs-lab">Persistence</span>
          ${bar(q, max, "b-pers")}<span class="num">${fmt.f4(q)}</span></div>
      </div>
      <p class="ex-delta ${d > 0 ? "up" : d < 0 ? "down" : ""}">
        Twin − persistence: <b>${fmt.signed(d)}</b> macro-F1 —
        ${d > 0 ? "the twin did better for this person."
                : d < 0 ? "persistence did better for this person."
                        : "the two tied for this person."}</p>
      <div class="gridwrap"><table class="grid">
        <thead><tr><th></th><th class="num">macro-F1</th>
          <th class="num">Accuracy</th><th class="num">MAE</th></tr></thead>
        <tbody>
          <tr><th>Digital twin</th><td class="num">${fmt.f4(t)}</td>
            <td class="num">${fmt.f3(k.twin.accuracy)}</td>
            <td class="num">${fmt.f3(k.twin.mae)}</td></tr>
          <tr><th>Persistence</th><td class="num">${fmt.f4(q)}</td>
            <td class="num">${fmt.f3(k.persistence.accuracy)}</td>
            <td class="num">${fmt.f3(k.persistence.mae)}</td></tr>
        </tbody></table></div>

      <div class="ex-agg">
        <h4>Across the whole held-out cohort</h4>
        <div class="ex-vs">
          <div class="ex-vs-row"><span class="ex-vs-lab">Digital twin</span>
            ${bar(aggT, aggMax, "b-twin")}<span class="num">${fmt.f4(aggT)}</span></div>
          <div class="ex-vs-row win"><span class="ex-vs-lab">Persistence</span>
            ${bar(aggP, aggMax, "b-pers")}<span class="num">${fmt.f4(aggP)}</span></div>
        </div>
        <p>The twin improved on every simpler personalised baseline we built —
          it beat the per-person calibrated global model by
          ${fmt.f3(aggT - agg.B4_calibrated.macro_f1)} macro-F1 — but
          <b>persistence remained stronger</b>. Carrying the last reported value
          forward is not a weak baseline here; that it wins is the finding.</p>
        <p class="hint">macro-F1 at K=80, the <b>regenerated</b> reproducible
          record. The <b>originally reported</b> twin figure was
          ${fmt.f4(HIST.headline.models.T_twin.macro_f1)}; both are preserved,
          and neither replaces the other.
          Twin better than persistence for
          <b>${META.nTwinBetter} of ${META.nScored}</b> participants at
          K=${META.kPrimary} — aggregate and individual behaviour differ.</p>
      </div>
    </div>
  </section>`;
}

/* ---------------------------------------------------------- comparison */
export function comparisonMarkup(a, b) {
  if (!a || !b) return "";
  const ka = scoreAt(a), kb = scoreAt(b);
  const cell = (v) => `<td class="num">${v}</td>`;
  const row = (label, va, vb, tip) => `<tr><th>${esc(label)}${tip ? " " + info(tip) : ""}</th>
    ${cell(va)}${cell(vb)}</tr>`;
  const strongerR = (a.autocorrelation ?? -9) > (b.autocorrelation ?? -9) ? a : b;
  const sameR = a.autocorrelation === b.autocorrelation;

  return `
    <div class="gridwrap"><table class="grid ex-cmp">
      <thead><tr><th></th><th class="num">${esc(a.id)}</th>
        <th class="num">${esc(b.id)}</th></tr></thead>
      <tbody>
        ${row("Observations", fmt.int(a.n_observations), fmt.int(b.n_observations))}
        ${row("Autocorrelation", fmt.f3(a.autocorrelation), fmt.f3(b.autocorrelation),
              META.definitions.autocorrelation)}
        ${row("Predictability band", esc(a.predictability_band || "—"),
              esc(b.predictability_band || "—"), META.definitions.predictability_band)}
        ${row("Variability (SD)", fmt.f2(a.variability_sd), fmt.f2(b.variability_sd))}
        ${row("Scored observations", ka ? fmt.int(ka.n_eval) : "—",
              kb ? fmt.int(kb.n_eval) : "—")}
        ${row("Twin macro-F1", ka ? fmt.f4(ka.twin.macro_f1) : "not scored",
              kb ? fmt.f4(kb.twin.macro_f1) : "not scored")}
        ${row("Persistence macro-F1", ka ? fmt.f4(ka.persistence.macro_f1) : "not scored",
              kb ? fmt.f4(kb.persistence.macro_f1) : "not scored")}
        ${row("Twin − persistence",
              ka ? fmt.signed(ka.twin_minus_persistence_macro_f1) : "—",
              kb ? fmt.signed(kb.twin_minus_persistence_macro_f1) : "—")}
      </tbody></table></div>

    <div class="msg">
      <b>What the observed data shows.</b>
      ${sameR ? `Both participants show the same lag-1 autocorrelation.`
              : `${esc(strongerR.id)} shows stronger temporal dependence in the
                 observed data (r = ${fmt.f3(strongerR.autocorrelation)} against
                 ${fmt.f3((strongerR === a ? b : a).autocorrelation)}).`}
      ${ka && kb ? `On their own held-out observations, the twin did better than
         persistence for ${ka.twin_minus_persistence_macro_f1 > 0 ? esc(a.id) : ""}
         ${ka.twin_minus_persistence_macro_f1 > 0 && kb.twin_minus_persistence_macro_f1 > 0 ? " and " : ""}
         ${kb.twin_minus_persistence_macro_f1 > 0 ? esc(b.id) : ""}
         ${ka.twin_minus_persistence_macro_f1 <= 0 && kb.twin_minus_persistence_macro_f1 <= 0
           ? "neither participant" : ""}.` : ""}
      This is a description of what was measured on two people. It is not
      evidence that personalisation would help either of them in future, and
      nothing here establishes a cause.
    </div>

    <div class="ex-sync">
      ${chartBlock(a, "Full history", "full", true)}
      ${chartBlock(b, "Full history", "full", true)}
    </div>
    <p class="hint">${hasSeries(a) && hasSeries(b)
      ? `Both charts use the same fixed 1–5 stress axis, so their shapes are
         directly comparable.`
      : `A chart is drawn only where the observation series is published;
         the comparison above uses every participant's statistics regardless.`}</p>`;
}

/* -------------------------------------------------------------- charts */
function chartBlock(p, title, view, compact = false) {
  const ph = phases(p);
  if (!hasSeries(p)) {
    return `<div class="ex-chart${compact ? " compact" : ""}">
      <p class="lg-title">${p.id} — ${title}</p>
      <p class="lg-empty">Observation series not published for ${p.id}.</p>
    </div>`;
  }
  return `<div class="ex-chart${compact ? " compact" : ""}">
    ${longitudinalSvg(p.series, { view, title: `${p.id} — ${title}`,
                                  height: compact ? 200 : 260 })}
    ${legend(ph, marksVisible(p.series, view))}
    ${!ph.hasPredictions ? `<p class="hint">No predictions are drawn: the frozen
      protocol did not score this participant, so none exist.</p>` : ""}
  </div>`;
}

function chartPanel(p) {
  const ph = phases(p);
  return `
  <section class="panel">
    <header><h3>Longitudinal history</h3>
      <span class="meta">${p.n_observations} reports over ${p.span_days} days</span></header>
    <div class="pad">
      ${!hasSeries(p) ? seriesUnavailable() : `
      <div class="ex-views" role="group" aria-label="Chart view">
        ${Object.entries(VIEWS).map(([k, v]) =>
          `<button type="button" class="ex-view${state.view === k ? " on" : ""}"
             data-view="${k}" title="${esc(v.hint)}">${esc(v.label)}</button>`).join("")}
        <button type="button" class="ex-view ex-reset" data-view="full">Reset</button>
      </div>
      ${longitudinalSvg(p.series, { view: state.view, height: 280 })}
      ${state.view === "evaluation" ? `<p class="hint">Showing the most recent
        ${Math.min(scoreAt(p)?.n_eval || 0, MARK_LIMIT)} of
        ${scoreAt(p)?.n_eval || 0} scored observations, so each prediction can
        be told apart. Full history shows every report.</p>` : ""}
      ${legend(ph, marksVisible(p.series, state.view))}
      <p class="hint">Reports are sparse and irregular, so the line breaks
        wherever consecutive reports are more than 7 days apart — the task's own
        horizon. Nothing is interpolated across a gap, and no confidence band is
        drawn, because the underlying output carries no per-observation
        uncertainty.</p>
      ${!ph.hasPredictions ? `<div class="msg"><b>No predictions for this
        participant.</b> ${esc(unscoredReason(p))}.</div>` : ""}`}
    </div>
  </section>`;
}

/* ---------------------------------------------------------------- page */
export function viewExplorer(root) {
  if (!state.id) state.id = defaultParticipant();
  const p = byId(state.id) || all()[0];
  const other = state.compare ? byId(state.compare) : null;
  const rows = sorted(state.sort, state.desc);

  const options = rows.map((q) => {
    const k = scoreAt(q);
    return `<option value="${esc(q.id)}"${q.id === p.id ? " selected" : ""}>
      ${esc(q.id)} — r ${fmt.f2(q.autocorrelation)}, ${q.n_observations} obs${
        k ? "" : " (not scored)"}</option>`;
  }).join("");

  root.innerHTML = `
  <div class="story ex">
    <section class="panel hero">
      <div class="pad">
        <p class="eyebrow">Evidence &amp; predictability explorer</p>
        <h2 class="q">How predictable is one person's stress, and did
          personalisation help them?</h2>
        <p>The headline is an average over ${META.nScored} held-out
          participants. Underneath it, people differ enormously — and the twin
          was better than persistence for
          <b>${META.nTwinBetter}</b> of them. Pick someone and look.</p>
        <p class="prov">${esc(META.provenance)}<br>
          <span class="dim">${esc(META.anonymisation)}</span></p>
      </div>
    </section>

    <section class="panel">
      <div class="pad ex-pick">
        <label class="ex-sel"><span>Participant</span>
          <select id="ex-participant">${options}</select></label>
        <label class="ex-sel"><span>Order by</span>
          <select id="ex-sort">${Object.entries(SORTS).map(([k, v]) =>
            `<option value="${k}"${state.sort === k ? " selected" : ""}>${esc(v.label)}</option>`).join("")}</select></label>
        <button type="button" class="linkb2" id="ex-dir">
          ${state.desc ? "High → low" : "Low → high"}</button>
        <span class="ex-count">${META.nTest} held-out participants ·
          ${META.nScored} scored at K=${META.kPrimary}</span>
      </div>
    </section>

    ${chartPanel(p)}
    ${evidencePanel(p)}
    ${strategyPanel(p)}

    <section class="panel">
      <header><h3>Compare with another participant</h3>
        <span class="meta">two people, the same system</span></header>
      <div class="pad">
        <label class="ex-sel"><span>Compare ${esc(p.id)} with</span>
          <select id="ex-compare">
            <option value="">— choose a participant —</option>
            ${rows.filter((q) => q.id !== p.id).map((q) =>
              `<option value="${esc(q.id)}"${q.id === state.compare ? " selected" : ""}>
                ${esc(q.id)} — r ${fmt.f2(q.autocorrelation)}</option>`).join("")}
          </select></label>
        ${other ? comparisonMarkup(p, other)
                : `<p class="hint">Choose someone to see the two side by side.
                   Picking a well-predictable and a near-unpredictable
                   participant shows the contrast most clearly.</p>`}
      </div>
    </section>
  </div>`;

  attachTooltips(root);
  wire(root);
}

function wire(root) {
  const rerender = () => viewExplorer(root);
  root.querySelector("#ex-participant")?.addEventListener("change", (e) => {
    state.id = e.target.value; state.compare = null; rerender();
  });
  root.querySelector("#ex-sort")?.addEventListener("change", (e) => {
    state.sort = e.target.value; rerender();
  });
  root.querySelector("#ex-dir")?.addEventListener("click", () => {
    state.desc = !state.desc; rerender();
  });
  root.querySelector("#ex-compare")?.addEventListener("change", (e) => {
    state.compare = e.target.value || null; rerender();
  });
  for (const b of root.querySelectorAll(".ex-view")) {
    b.addEventListener("click", () => { state.view = b.dataset.view; rerender(); });
  }
  for (const b of root.querySelectorAll(".ex-i")) {
    b.addEventListener("click", () => {
      const open = b.getAttribute("aria-expanded") === "true";
      for (const o of root.querySelectorAll(".ex-i")) o.setAttribute("aria-expanded", "false");
      b.setAttribute("aria-expanded", String(!open));
    });
  }
}

/** Let another page open the explorer on a chosen participant. */
export function selectParticipant(id) {
  if (byId(id)) { state.id = id; state.compare = null; }
}
